package telemetry

import (
	"encoding/json"
	"os"
	"runtime"
	"strings"
	"time"

	"github.com/denisbrodbeck/machineid"
	"github.com/posthog/posthog-go"
	"github.com/spf13/cobra"
	"github.com/spf13/pflag"
)

// EventPayload represents the data passed to the detached subprocess
type EventPayload struct {
	Event      string            `json:"event"`
	DistinctID string            `json:"distinct_id"`
	Properties map[string]any    `json:"properties"`
	Timestamp  time.Time         `json:"timestamp"`
	APIKey     string            `json:"api_key"`
	Endpoint   string            `json:"endpoint"`
}

// debugLog writes debug output to stderr when ANALYTICS_DEBUG=1
func debugLog(format string, args ...any) {
	if os.Getenv("ANALYTICS_DEBUG") == "1" {
		//nolint:forbidigo // Debug logging to stderr is intentional
		_, _ = os.Stderr.WriteString("[analytics-debug] ")
		//nolint:errcheck,forbidigo // Debug logging - best effort
		os.Stderr.WriteString(strings.TrimRight(format, "\n"))
		if len(args) > 0 {
			//nolint:errcheck,forbidigo // Debug logging - best effort
			os.Stderr.WriteString(": ")
			for i, arg := range args {
				if i > 0 {
					//nolint:errcheck,forbidigo // Debug logging - best effort
					os.Stderr.WriteString(", ")
				}
				//nolint:errcheck,forbidigo // Debug logging - best effort
				_, _ = os.Stderr.WriteString(stringifyArg(arg))
			}
		}
		//nolint:errcheck,forbidigo // Debug logging - best effort
		os.Stderr.WriteString("\n")
	}
}

// stringifyArg converts an argument to string for debug logging
func stringifyArg(arg any) string {
	switch v := arg.(type) {
	case string:
		return v
	case error:
		return v.Error()
	default:
		b, err := json.Marshal(v)
		if err != nil {
			return "<marshal error>"
		}
		return string(b)
	}
}

// TrackCommandDetached tracks a command execution by spawning a detached subprocess.
// This returns immediately without blocking the CLI.
func TrackCommandDetached(cmd *cobra.Command, strategy, agent string, isEntireEnabled bool, version string) {
	// Check opt-out environment variables
	if os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
		debugLog("Telemetry disabled via ENTIRE_TELEMETRY_OPTOUT")
		return
	}
	if os.Getenv("DO_NOT_TRACK") == "1" {
		debugLog("Telemetry disabled via DO_NOT_TRACK")
		return
	}

	if cmd == nil {
		debugLog("Skipping nil command")
		return
	}

	// Skip hidden commands
	if cmd.Hidden {
		debugLog("Skipping hidden command", cmd.CommandPath())
		return
	}

	// Get machine ID for distinct_id
	machineID, err := machineid.ProtectedID("entire-cli")
	if err != nil {
		debugLog("Failed to get machine ID", err)
		return
	}

	// Collect flag names (not values) for privacy
	var flags []string
	cmd.Flags().Visit(func(flag *pflag.Flag) {
		flags = append(flags, flag.Name)
	})

	selectedAgent := agent
	if selectedAgent == "" {
		selectedAgent = "auto"
	}

	properties := map[string]any{
		"command":          cmd.CommandPath(),
		"strategy":         strategy,
		"agent":            selectedAgent,
		"isEntireEnabled":  isEntireEnabled,
		"cli_version":      version,
		"os":               runtime.GOOS,
		"arch":             runtime.GOARCH,
	}

	if len(flags) > 0 {
		properties["flags"] = strings.Join(flags, ",")
	}

	payload := EventPayload{
		Event:      "cli_command_executed",
		DistinctID: machineID,
		Properties: properties,
		Timestamp:  time.Now(),
		APIKey:     PostHogAPIKey,
		Endpoint:   PostHogEndpoint,
	}

	payloadJSON, err := json.Marshal(payload)
	if err != nil {
		debugLog("Failed to marshal payload", err)
		return
	}

	debugLog("Spawning detached analytics subprocess")
	if err := spawnDetachedAnalytics(string(payloadJSON)); err != nil {
		debugLog("Failed to spawn analytics subprocess", err)
	}
}

// SendEvent processes an event payload in the detached subprocess.
// This is called by the hidden __send_analytics command.
func SendEvent(payloadJSON string) {
	debugLog("SendEvent called with payload length", len(payloadJSON))

	var payload EventPayload
	if err := json.Unmarshal([]byte(payloadJSON), &payload); err != nil {
		debugLog("Failed to unmarshal payload", err)
		return
	}

	debugLog("Creating PostHog client for event", payload.Event)

	// Create PostHog client - no need for fast timeouts since we're detached
	client, err := posthog.NewWithConfig(payload.APIKey, posthog.Config{
		Endpoint:     payload.Endpoint,
		Logger:       silentLogger{},
		DisableGeoIP: posthog.Ptr(true),
	})
	if err != nil {
		debugLog("Failed to create PostHog client", err)
		return
	}
	defer func() {
		debugLog("Closing PostHog client")
		_ = client.Close()
	}()

	// Build properties
	props := posthog.NewProperties()
	for k, v := range payload.Properties {
		props.Set(k, v)
	}

	debugLog("Enqueueing event")
	if err := client.Enqueue(posthog.Capture{
		DistinctId: payload.DistinctID,
		Event:      payload.Event,
		Properties: props,
		Timestamp:  payload.Timestamp,
	}); err != nil {
		debugLog("Failed to enqueue event", err)
		return
	}

	debugLog("Event sent successfully")
}

//go:build unix

package telemetry

import (
	"os"
	"os/exec"
	"syscall"
)

// spawnDetachedAnalytics spawns a detached subprocess to send analytics.
// On Unix, this uses process group detachment so the subprocess continues
// after the parent exits.
func spawnDetachedAnalytics(payloadJSON string) error {
	executable, err := os.Executable()
	if err != nil {
		return err
	}

	//nolint:gosec // G204: payloadJSON is controlled internally, not user input
	cmd := exec.Command(executable, "__send_analytics", payloadJSON)

	// Detach from parent process group so subprocess survives parent exit
	cmd.SysProcAttr = &syscall.SysProcAttr{
		Setpgid: true,
	}

	// Don't hold the working directory
	cmd.Dir = "/"

	// Inherit environment (may be needed for network config)
	cmd.Env = os.Environ()

	// Don't capture stdout/stderr - let it go to /dev/null
	cmd.Stdout = nil
	cmd.Stderr = nil

	// Start the process (non-blocking)
	if err := cmd.Start(); err != nil {
		return err
	}

	// Release the process so it can run independently
	//nolint:errcheck // Best effort - process should continue regardless
	_ = cmd.Process.Release()

	debugLog("Subprocess started with PID", cmd.Process.Pid)
	return nil
}

//go:build windows

package telemetry

// spawnDetachedAnalytics on Windows falls back to synchronous event sending.
// Windows process detachment requires different handling (CREATE_NEW_PROCESS_GROUP, etc.)
// and the existing fast timeouts make synchronous acceptable.
func spawnDetachedAnalytics(payloadJSON string) error {
	debugLog("Windows: falling back to synchronous SendEvent")
	SendEvent(payloadJSON)
	return nil
}

